using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using SportRace.Domain.Entities; using System.Net.Http.Json;
namespace SportRace.Web.Pages.Admin.AgeGroups;
public class CreateModel : PageModel { private readonly IHttpClientFactory _factory; [BindProperty] public AgeGroup AgeGroup {get;set;}=new(); public CreateModel(IHttpClientFactory factory)=>_factory=factory; public async Task<IActionResult> OnPostAsync(){ if(AgeGroup.MinAge<0 || AgeGroup.MaxAge<AgeGroup.MinAge){ModelState.AddModelError("", "Невалиден възрастов диапазон."); return Page();} var r=await _factory.CreateClient("SportRaceApi1").PostAsJsonAsync("api/agegroups",AgeGroup); if(!r.IsSuccessStatusCode){ModelState.AddModelError("","Грешка при създаване.");return Page();} return RedirectToPage("Index");}}
